package com.cxy.workbench;
import android.content.*;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Five persistent nodes and a focused detail panel; telemetry updates views in place. */
final class DevicePage extends LinearLayout {
 final MainActivity a;final DeviceOrbit orbit;final LinearLayout details;final ArrayList<Runnable> bindings=new ArrayList<>();JSONObject snapshot;String selected="overview";
 DevicePage(MainActivity a){super(a);this.a=a;setOrientation(VERTICAL);orbit=new DeviceOrbit(a,this::choose);addView(orbit,new LayoutParams(-1,a.dp(310)));details=a.column();addView(details);}
 void choose(String id){a.device=id.equals(selected)?"overview":id;select(a.device);a.render();}
 void update(JSONObject value){snapshot=value;orbit.update(value);for(Runnable r:bindings)r.run();}
 void select(String id){if(!Arrays.asList("overview","gateway","mac","winpc","linux","phone").contains(id))id="overview";if(selected.equals(id))return;selected=id;orbit.focus(id);bindings.clear();details.removeAllViews();if(!id.equals("overview")){if(id.equals("gateway"))gateway();else hardware();for(Runnable r:bindings)r.run();HyperStyle.enter(details);}}
 JSONObject sample(){return selected.equals("gateway")?snapshot==null?null:snapshot.optJSONObject("gateway"):DeviceText.sample(snapshot,selected);}
 boolean fresh(){return DeviceText.hardwareFresh(sample(),System.currentTimeMillis());}
 void bind(Runnable update){bindings.add(update);}
 double ratio(JSONObject data,String used,String total){double n=DeviceText.number(data,total),u=DeviceText.number(data,used);return n>0&&u>=0?u/n*100:Double.NaN;}
 String capacity(JSONObject data,String used,String total){return CardMetrics.bytes(DeviceText.number(data,used),false)+" / "+CardMetrics.bytes(DeviceText.number(data,total),false);}
 LinearLayout heading(){LinearLayout card=DeviceCards.panel(a,details);LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);card.addView(row);TextView title=a.text(selected.equals("gateway")?"家庭网关":DeviceText.title(selected),21,HyperStyle.ink(a));title.setTypeface(Typeface.create("sans-serif-medium",0));row.addView(title,new LayoutParams(0,-2,1));a.iconButton(row,"close","收起设备",()->{a.device="overview";select("overview");a.render();});LinearLayout networks=a.column();card.addView(networks);TextView state=a.text("",14,HyperStyle.muted(a));card.addView(state);bind(()->{networks.removeAllViews();DeviceCards.statusChips(a,networks,sample(),System.currentTimeMillis());JSONObject d=sample();boolean current=selected.equals("gateway")?proxyFresh():fresh();boolean hasData=selected.equals("gateway")?proxy()!=null:Store.sampleMillis(d,"receivedAt")>0&&(!selected.equals("phone")||d.optBoolean("hardwareSampleAvailable",false));String host=d==null||selected.equals("phone")?"":d.optString("host","");state.setText((current?"已更新":hasData?"上次数据":"等待采样")+(host.isEmpty()?"":" · "+host));});return card;}
 void hardware(){
  LinearLayout card=heading();boolean phone=selected.equals("phone");LinearLayout metrics=new LinearLayout(a);card.addView(metrics);String[] labels=phone?new String[]{"电量","内存","存储"}:new String[]{"CPU","GPU","内存"};int[] colors={HyperStyle.accent(a),0xff8966db,0xff20a887};
  for(int n=0;n<3;n++){final int index=n;LinearLayout col=a.column();col.setGravity(Gravity.CENTER);metrics.addView(col,new LayoutParams(0,-2,1));PercentRing ring=new PercentRing(a,labels[n],colors[n],false);col.addView(ring,new LayoutParams(-1,a.dp(116)));TextView amount=a.text("",12,HyperStyle.muted(a));amount.setGravity(Gravity.CENTER);amount.setMinHeight(a.dp(30));col.addView(amount);bind(()->{JSONObject d=sample();double value;if(phone){if(index==0)value=DeviceText.number(d,"batteryPercent");else if(index==1)value=ratio(d,"memoryUsed","memoryTotal");else value=storageRatio(d);}else value=index==0?DeviceText.number(d,"cpu"):index==1?DeviceText.number(d,"gpu"):ratio(d,"memoryUsed","memoryTotal");ring.value(value,fresh());if(phone&&index==0)amount.setText(d!=null&&d.optBoolean("batteryCharging")?"充电中":"");else if((phone&&index==1)||(!phone&&index==2))amount.setText(capacity(d,"memoryUsed","memoryTotal"));else amount.setText("");});}
  if(phone){TextView unavailable=a.text("CPU / GPU 暂未采集  ⓘ",14,HyperStyle.muted(a));unavailable.setGravity(Gravity.CENTER);unavailable.setPadding(0,a.dp(12),0,a.dp(8));unavailable.setOnClickListener(v->HyperStyle.dialog(new android.app.AlertDialog.Builder(HyperStyle.dialogContext(a)).setTitle("手机指标").setMessage("内存、内部存储和电量来自 Android 系统接口。当前版本未取得可靠的整机 CPU / GPU 占用来源；本应用用量或频率不能替代整机占用百分比。未采集的指标保留为空。").setPositiveButton("知道了",null).create()));card.addView(unavailable);}else{LinearLayout rates=new LinearLayout(a);rates.setPadding(0,a.dp(12),0,0);card.addView(rates);TextView down=a.text("",17,HyperStyle.accent(a)),up=a.text("",17,0xff8966db);rates.addView(down,new LayoutParams(0,-2,1));rates.addView(up,new LayoutParams(0,-2,1));bind(()->{JSONObject d=sample();down.setText("↓ "+(fresh()?CardMetrics.bytes(DeviceText.number(d,"download"),true)+"/s":"—"));up.setText("↑ "+(fresh()?CardMetrics.bytes(DeviceText.number(d,"upload"),true)+"/s":"—"));});}
  a.section(details,"存储","","disk",HyperStyle.accent(a));LinearLayout disks=DeviceCards.panel(a,details);final String[] diskShape={""};final ArrayList<Runnable> diskBindings=new ArrayList<>();bind(()->{JSONObject d=sample();JSONArray volumes=d==null?null:d.optJSONArray("disks");String shape="";if(volumes!=null)for(int n=0;n<volumes.length();n++){JSONObject volume=volumes.optJSONObject(n);if(volume!=null)shape+=n+":"+volume.optString("name")+"|";}if(!shape.equals(diskShape[0])||disks.getChildCount()==0){diskShape[0]=shape;disks.removeAllViews();diskBindings.clear();if(volumes==null||volumes.length()==0)disks.addView(a.text("暂未取得存储数据",16,HyperStyle.muted(a)));else for(int n=0;n<volumes.length();n++){final int index=n;JSONObject volume=volumes.optJSONObject(n);if(volume==null)continue;if(n>0)a.divider(disks,70);LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,a.dp(12),0,a.dp(12));disks.addView(row);PercentRing ring=new PercentRing(a,"存储",HyperStyle.accent(a),true);row.addView(ring,new LayoutParams(a.dp(62),a.dp(62)));LinearLayout text=a.column();text.setPadding(a.dp(14),0,0,0);row.addView(text,new LayoutParams(0,-2,1));text.addView(a.text(CardPainter.displayDisk(volume.optString("name","存储")),17,HyperStyle.ink(a)));TextView amount=a.text("",14,HyperStyle.muted(a));text.addView(amount);diskBindings.add(()->{JSONObject current=sample();JSONArray list=current==null?null:current.optJSONArray("disks");JSONObject disk=list==null?null:list.optJSONObject(index);ring.value(ratio(disk,"used","total"),fresh());amount.setText(capacity(disk,"used","total"));});}}for(Runnable r:diskBindings)r.run();});
 }
 double storageRatio(JSONObject d){JSONArray disks=d==null?null:d.optJSONArray("disks");double used=0,total=0;if(disks!=null)for(int n=0;n<disks.length();n++){JSONObject disk=disks.optJSONObject(n);double t=DeviceText.number(disk,"total"),u=DeviceText.number(disk,"used");if(t>0&&u>=0){used+=u;total+=t;}}return total>0?used/total*100:Double.NaN;}
 JSONObject proxy(){JSONObject linux=DeviceText.sample(snapshot,"linux");return linux==null?null:linux.optJSONObject("proxy");}
 boolean proxyFresh(){JSONObject linux=DeviceText.sample(snapshot,"linux"),p=proxy();long at=p==null?0:(long)(p.optDouble("sampledAtUnix",0)*1000);return DeviceText.hardwareFresh(linux,System.currentTimeMillis())&&at>0&&System.currentTimeMillis()-at<18000;}
 void gateway(){LinearLayout card=heading();card.addView(a.text("当前出口",14,HyperStyle.muted(a)));TextView exit=a.text("",23,HyperStyle.accent(a));card.addView(exit);bind(()->{JSONObject p=proxy();exit.setText((proxyFresh()?"":"上次 · ")+(p==null?"未知":p.optString("selected","未知")));});a.section(details,"出口节点","","gateway",HyperStyle.accent(a));LinearLayout nodes=DeviceCards.panel(a,details);final String[] shape={""};final ArrayList<Runnable> nodeBindings=new ArrayList<>();bind(()->{JSONObject p=proxy();JSONArray list=p==null?null:p.optJSONArray("nodes");String key="";if(list!=null)for(int n=0;n<list.length();n++){JSONObject node=list.optJSONObject(n);if(node!=null)key+=node.optString("name")+"|";}if(!key.equals(shape[0])||nodes.getChildCount()==0){shape[0]=key;nodes.removeAllViews();nodeBindings.clear();if(list==null||list.length()==0)nodes.addView(a.text("节点状态尚未取得",16,HyperStyle.muted(a)));else for(int n=0;n<list.length();n++){final int index=n;if(n>0)a.divider(nodes,0);LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,a.dp(14),0,a.dp(14));nodes.addView(row);LinearLayout copy=a.column();row.addView(copy,new LayoutParams(0,-2,1));TextView name=a.text("",17,HyperStyle.ink(a)),status=a.text("",14,HyperStyle.muted(a)),latency=a.text("",22,HyperStyle.accent(a));copy.addView(name);copy.addView(status);row.addView(latency);nodeBindings.add(()->{JSONObject current=proxy();JSONArray arr=current==null?null:current.optJSONArray("nodes");JSONObject node=arr==null?null:arr.optJSONObject(index);if(node==null)return;long now=System.currentTimeMillis();boolean recent=CardMetrics.probeRecent(proxyFresh(),DeviceWidgets.probeTime(node),now),healthy=CardMetrics.nodeFresh(proxyFresh(),node.optString("health"),DeviceWidgets.probeTime(node),now);name.setText(node.optString("name"));status.setText(recent?"HTTP · "+(node.optBoolean("selected")?"当前 · ":"")+DeviceWidgets.health(node.optString("health")):"探测待更新");latency.setText(healthy&&!node.isNull("latencyMs")?String.format(Locale.CHINA,"%.0f ms",node.optDouble("latencyMs")):"—");});}}for(Runnable r:nodeBindings)r.run();});nodes.addView(a.text("HTTP 探测",12,HyperStyle.muted(a)));}
}
